const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>zh(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes={'レダ':'蕾达','カイ':'凯伊','ディートリヒ':'迪托利希','セオドラ':'赛奥朵拉','救世篇':'第三部'};
const pages={overview:'路线攻略',sources:'来源',preferences:'偏好与规划',characters:'全角色图鉴',recruit:'招募与声望',classes:'职业资格',training:'技能与斗技场',equipment:'装备与材料',map:'探索大地图',mechanics:'周目与继承'};
let DB,PINS=[],mapLoaded=false,mapLoading=false,route='レダ',query='',family='all',mapType='all',mapScale=1,checked={};try{checked=JSON.parse(localStorage.getItem('guide-v2')||'{}')}catch{};route=checked.route||route;if(checked.dark)document.body.classList.add('dark');
const statNames={hp:'生命',str:'力量',mag:'魔力',spd:'速度',dex:'技巧',def:'防御',res:'魔防',lck:'幸运',cha:'魅力'};
const link=(url,label)=>guidePage()==='sources'&&url?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`:'';
const tag=(t,cls='')=>`<span class="tag ${cls}">${esc(t)}</span>`;
const title=(k,h,p)=>`<div class="page-title"><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const note=t=>`<div class="note">${t}</div>`;
function persist(){checked.route=route;checked.dark=document.body.classList.contains('dark');localStorage.setItem('guide-v2',JSON.stringify(checked))}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function className(n){return DB.classNames[n]||zh(n)}function skillName(n){return DB.skills[n]||n}function classBy(n){return DB.classes.find(c=>c.title===n||c.cn===n)}
function joinRows(c){const main=c.joinDetails.filter(j=>j.route===route+'編'&&j.method!=='対象外');const common=c.joinDetails.filter(j=>j.route==='共通'&&j.method!=='対象外');return route==='救世篇'?(common.length?common:c.joinDetails.filter(j=>j.method!=='対象外')):[...main,...common]}
function heroIds(){return {レダ:['レダ','カターニャ','シロッコ','ムウ','オリンピア','ソフィア','バッカニア','エスメラルダ'],カイ:['カイ','グザラン','フィアナ','カターニャ','ニネ','ウーシュラ','アレキサンドラ','ナジャ'],ディートリヒ:['ディートリヒ','キロイカ','ロレッタ','ミカエラ','トビヤス','エスメラルダ'],セオドラ:['セオドラ','ソフィア','ハルヴィン','ウルタンド','サラン','ダイトウ'],救世篇:['レダ','カイ','ディートリヒ','セオドラ','救世主']}[route]||[]}
function requirement(c){let a=c.must.map(x=>x.join(' ')),b=c.any.map(x=>x.join(' '));return [c.col_2||'',...a,b.length?'任选其一：'+b.join(' / '):''].filter(Boolean).join('；')||'特殊条件 / 无技能要求'}
function joinText(c){const rows=joinRows(c);if(rows.length){let j=rows[0],s=j.method==='ストーリー'?'剧情加入':j.method==='スカウト'?'招募':j.method;return [s,j.part,j.chapter,j.renown?'声望'+j.renown:'',j.support?'支援'+j.support:''].filter(Boolean).join(' · ')}const r=c.routes[route];return r?`声望 ${r.renown} · 支援 ${r.support}`:route==='救世篇'?'查看各路线入队与融合记录':'当前路线无入队记录'}
function portrait(c,eager=false){return `<img class="portrait" src="${c.portraitFile}?v=79" alt="${esc(c.cn)}头像" loading="${eager?'eager':'lazy'}" fetchpriority="${eager?'high':'auto'}" decoding="async" width="76" height="76">`}
function baseTraining(){return title('培养与训练','练到资格，再补短板','第一部用技能等级作为停止线，不用固定属性数值硬刷每个人；成长具有随机性，加入等级和当前职业也不同。')+`<div class="grid-two"><article class="feature"><h2>升级时切换职业，可行吗？</h2><p>已取得资格的职业可以切换；升级采用当前职业的成长修正。比如勇士力量成长+20%，剑客速度成长+15%。先看资格与阶段解锁，不能在低级时直接切高级。</p><p>实践：接近升级时切到目标成长职业 → 确认当前职业 → 在该职业获得升级 → 需要时再切回作战职业。不要把职业面板临时加成误认为永久基础属性。</p>${link('https://gamewith.jp/fefw/573025','职业成长')}</article><article class="feature"><h2>蕾达当舞者，还要练吗？</h2><p>要。舞者本身速度成长+25%，速度与生存仍重要；舞姬熟练和再行动决定辅助价值。力量/魔力不是“全部无用”，但纯辅助方案不必为了攻击面板一直刷斗技场。</p><p>满足剑B或弓B、资格与关键熟练后，把训练资源留给输出位；若走攻击弓或魔剑分支，再继续主武器与对应攻击属性。</p>${link('https://game8.jp/fe-banshisenko/816861','舞者资格')}</article></div><div class="section-head"><h2>第一部技能停止线</h2></div><div class="table-wrap"><table><thead><tr><th>阶段</th><th>目标等级</th><th>继续刷的理由</th><th>可以停止的条件</th></tr></thead><tbody><tr><td>前期 / 初级</td><td>主技能D附近，按职业要求</td><td>拿下一档职业资格</td><td>可用战技、基本命中与角色职责已满足</td></tr><tr><td>中级 / 等级20附近</td><td>主技能C；副技能按资格</td><td>确定上级终点后向B推进</td><td>不要把所有武器都均摊到C</td></tr><tr><td>上级 / 等级35附近</td><td>主技能B；多要求职业逐条补</td><td>职业熟练奖励、重点战技、A阶武器</td><td>已有上级主职且队伍职责稳定</td></tr><tr><td>第一部结尾</td><td>核心武器B–A，按装备与战技需要</td><td>如卡拉的弓需要弓A；不是人人必须A</td><td>备选只需能上场，不要求全技能S</td></tr></tbody></table></div>${note('技能等级门槛可确认；逐级经验累计表和所有训练项目的固定经验效率，本版不编造数值。页面“停止线”是训练建议，不是必达属性。自动训练与主动斗技场应分别看游戏结算，不保证所有条件下角色经验都为零。')}${multiClassTable()}<div class="section-head"><h2>中期 / 后期多职业，三种合理目的</h2></div><div class="phase-line"><article class="phase"><small>01 / 补成长</small><h3>力量不够的剑系</h3><p>剑术B → 勇士取得资格 → 在勇士中升级 → 回剑职作战。无需为了资格额外练斧B；代价是勇士魔力成长−5%、速度修正0。</p></article><article class="phase"><small>02 / 拿熟练</small><h3>剑客 → 侍道 / 勇士</h3><p>剑客熟练「技の冴え」服务必杀伤害；侍道熟练「残心」服务必杀击杀后的续航；勇士「熟練の技」服务战技命中。拿到再回终职。</p></article><article class="phase"><small>03 / 换战术</small><h3>法师 → 持剑魔法职业</h3><p>先在魔法职业中补魔力，再拿剑C用雷电剑；后期魔剑骑士还需剑B、黑魔D、马D。不要把低魔力物理角色直接认定为最强魔剑。</p></article></div>${link('https://gamewith.jp/fefw/575722','多职业熟练培养')}<div class="section-head"><h2>当前路线：每人该练什么</h2></div><div class="table-wrap"><table><thead><tr><th>角色 / 职责</th><th>技能与停止线</th><th>斗技场项目</th><th>上级资格</th></tr></thead><tbody>${DB.characters.filter(available).map(c=>`<tr><td><button class="text-button" data-char="${c.id}">${c.cn}</button><small>${c.role}</small></td><td>${c.stop}<small>主方向：${c.coreSkill}；擅长：${c.good.split(':').map(skillName).join(' / ')}</small></td><td>${esc(projectSuggestions(c).map(p=>p.name).join(' / ')||'需其他训练方式')}</td><td>${c.upper?className(c.upper)+'<small>'+esc(requirement(classBy(c.upper)))+'</small>':'按入队职业补缺口'}</td></tr>`).join('')}</tbody></table></div>`}
function gearCard(e){return `<article class="equip-card" id="gear-${e.id}"><div class="section-head"><h3>${esc(e.name)}</h3>${tag(e.phase)}</div><p><b>${esc(e.rank)}</b> · ${esc(e.purpose)}</p><p>${esc(e.effect)}</p><h4>获取途径</h4>${e.sourcesList.map(s=>`<div class="source-row">${tag(s.kind)}<span>${esc(s.text)} ${s.place?`<button class="text-button" data-map="${esc(s.place)}">地图 ↗</button>`:''}</span></div>`).join('')}<h4>兑换材料与地点</h4>${e.materials.length?`<ul class="materials">${e.materials.map(m=>`<li><b>${esc(m[0])} × ${m[2]}</b><p>${esc(m[3])}</p><button class="text-button" data-map="${esc(m[1])}">地图搜索材料 ↗</button>${link(m[4],'材料资料')}</li>`).join('')}</ul>`:'<p class="muted">此路径不需要商会材料兑换。</p>'}<p class="muted">${esc(e.availabilityNote||'')} ${link(e.url,'装备出处')}</p></article>`}
function baseMapPage(){if(!mapLoaded){loadMap();return title('探索地图','探索大地图','地图按需载入，不影响角色图鉴加载。')+'<p>正在载入中文点位…</p>'}const list=PINS.filter(p=>p.area===route&&(mapType==='all'||p.type===mapType)&&`${p.name} ${p.info} ${p.type}`.includes(query));const types=[...new Set(PINS.filter(p=>p.area===route).map(p=>p.type))];return title('探索地图','探索大地图','滚轮以鼠标位置为中心缩放；按住地图拖拽。高清瓦片按视野载入；点击标记查看材料和武器购买信息。')+toolbar('搜索材料或地点，如 太阳果、威利村…')+`<div class="toolbar"><div class="segments"><button data-maptype="all" class="${mapType==='all'?'active':''}">全部</button>${types.map(t=>`<button data-maptype="${esc(t)}" class="${mapType===t?'active':''}">${esc(t)}</button>`).join('')}</div><div><button data-zoom="1" aria-label="放大地图">＋</button><button data-zoom="-1" aria-label="缩小地图">−</button><button data-zoom="0">复位</button></div></div><div class="map-layout"><div class="map-viewport" tabindex="0" aria-label="可缩放拖动的地图"><div class="map-canvas"><img class="world-map" src="world-map.webp" alt="中文世界地图" decoding="async" draggable="false"><div class="map-tiles"></div><div class="map-pins">${list.map(p=>`<button class="pin ${['蔬菜','鱼','矿石','道具'].includes(p.type)?'gather-pin':'shop-pin'}" style="left:${p.x}%;top:${p.y}%" data-pin="${p.id}" title="${esc(p.name+' · '+p.type)}" aria-label="${esc(p.name+' · '+p.type)}">${['据点','小据点','神殿','驿站'].includes(p.type)||query?`<span class="pin-label">${esc(p.name)}</span>`:''}</button>`).join('')}</div></div></div><aside class="map-results"><h3>${list.length}个匹配点位</h3><p class="muted">绿：探索材料 · 金：城镇 / 其他</p>${list.map(p=>`<button class="map-result" data-pin="${p.id}"><b>${esc(p.name)}</b><small>${esc(p.type)}</small><p>${esc(p.info)}</p></button>`).join('')||'<p>当前路线无匹配点，尝试其他路线或材料名称。</p>'}</aside></div>${note('中文底图与标记采用同一坐标系。地图不能替代章节开放条件；武器价格与库存请结合装备来源页核对。第三部地图点位仍不完整。')}<p class="muted">${link('https://fire-emblem-fw.site/map.html','中文地图与点位参考')}</p>`}
function planning(){return title('终局规划','从四条路线，养到五支部队','第三部起初2队，第三区分3队，之后最多5队；第五区分需要按5队准备。终战25人框架，比只记“三队”更稳妥。')+`${preferencePlan()}<div class="stats"><div class="stat"><strong>6–8</strong><div><b>每线重点</b><small>先养主力，少量备选随战斗跟上</small></div></div><div class="stat"><strong>24–32</strong><div><b>全路线培养席位</b><small>重复培养同角色不增加人数</small></div></div><div class="stat"><strong>5 × 5</strong><div><b>终局职责框架</b><small>不是全阶段固定战斗编制</small></div></div></div><div class="table-wrap"><table><thead><tr><th>路线</th><th>基础培养候选（偏好分工见上表）</th><th>跨线重复位处理</th></tr></thead><tbody><tr><td>蕾达</td><td>蕾达、卡塔妮雅、西洛可、穆、奥琳琵娅、巴卡尼亚；索绯雅 / 艾丝梅拉尔达为替补</td><td>优先确立再行动、拳系和魔法输出；共享角色可留另一线补成长</td></tr><tr><td>凯伊</td><td>凯伊、古扎岚、绯亚娜、卡塔妮雅、妮涅、乌修拉；亚历珊德拉 / 哪吒备选</td><td>第五章骑宠开放后，优先给飞骑、弓骑与治疗骑兵培养友好；先用剧情核心，声望达标再招募高成本队员</td></tr><tr><td>迪托利希</td><td>迪托利希、奇洛伊卡、罗蕾塔、艾丝梅拉尔达、米迦艾拉、托比亚斯；波拿帕尔特 / 哥莱亚斯补位</td><td>卡塔妮雅若已在蕾达线培养，第二轮可补力量、防御或所需技能，不算新增角色</td></tr><tr><td>赛奥朵拉</td><td>赛奥朵拉、索绯雅、哈尔温、乌尔坦德、沙兰、大刀；媞雅拉 / 嘉丝敏备选</td><td>穆可跨线补不同成长与熟练；同角色融合只形成一名最终单位</td></tr></tbody></table></div>${note('6–8人为资源分配建议，没有证据证明是系统硬上限。剧情入队、晚加入和声望成本不同；先保证当前战斗能过，再安排跨线互补。第二部齐利科、内森可按共通事件补入；第三部欧露赫露、谭利穆恩、贝特兰、爱娜特莉亚等晚加入角色可以补缺，不必在第一部把40人练满。')}<div class="section-head"><h2>五队怎么搭：按职责补人</h2></div><div class="squad-grid">${['主角攻坚队','机动突击队','远程压制队','魔法破防队','防线与替补队'].map((n,i)=>`<article class="feature"><h3>${n}</h3><p>${[['主角 / 救世主','近战输出','远程','治疗','机动或再行动'],['骑飞输出','物理近战','弓或魔法','治疗','第二机动'],['弓核心','第二输出','前排','治疗','功能位'],['法术核心','持剑魔法或第二法师','物理前排','治疗','机动'],['稳定前排','物理输出','远程','治疗','缺口替补']][i].join(' + ')}</p></article>`).join('')}</div><p>不要把所有治疗者、远程武器或再行动角色塞进一队。五队并非每队都要配舞者；蕾达优先服务当前难度最高的主攻队。部分后期战斗会合并两支队伍并派出17人，提前保留跨队互补。</p><p>${link('https://gamewith.jp/fefw/577934','第三部编制')} · ${link('https://gamewith.jp/fefw/578269','第五区分五队与17人战斗')} · ${link('https://gamewith.jp/fefw/578066','最终战')}</p><div class="section-head"><h2>为什么要养备选？</h2></div><p>加入晚不等于弱：爱娜特莉亚、齐利科、欧露赫露等角色可补后期缺口。低力量高速度的剑 / 弓角色可负责机动与战技；高力量低速度角色优先做特效与前排，少按高速输出的标准评价。每人图鉴都有成长数据、主线及备选方向。</p>`}
function mechanics(){return title('周目继承','周目与继承','把“账户共通进度”“角色培养融合”“物品继承系统”分开理解，才能避免白刷。')+equipmentInheritancePanel()+`<div class="feature"><h2>同一主角能多周目培养，但属性不相加</h2><p>官方访谈先明确讨论“同一路线可以重复游玩”，随后举例“同一主角分别培养为剑士与魔导士并通关”，因此确实包含主角本人重复培养。下一段才另举跨路线共同队员的例子。两种培养方式都存在。具体计算规则参考因果融合资料：属性按每项较高值保留，例如两轮力量40和35，结果是40，绝不是75；技能与战技的获得成果可以继承。</p><p>四主角在第二部完成 / 跳过时自动融合培养结果，不需要手动用因果碎片合主角。只重打一遍第一部后立刻停下，不能直接保证第三部主角已经更新；稳妥流程是推进到第二部结束。</p>${link('https://www.nintendo.com/jp/interview/aacsa/02.html','任天堂官方访谈')} · ${link('https://gamewith.jp/fefw/579505','因果融合')}</div><div class="table-wrap"><table><thead><tr><th>内容</th><th>保留 / 处理方式</th><th>注意</th></tr></thead><tbody><tr><td>角色基础属性</td><td>融合逐项取高</td><td>不叠加数值；临时职业加成不是额外永久属性</td></tr><tr><td>已学技能与战技</td><td>不同路线已学战技、特技可融合继承</td><td>相同技能不产生双份效果；仍受职业、武器与槽位限制。迪托利希强化战技也属于培养成果</td></tr><tr><td>技能经验</td><td><b>资料有分歧，暂不保证累加</b></td><td>游戏维基写较高等级；应用媒体写经验相加。本版不据此安排重复刷经验</td></tr><tr><td>探索地图 / 采集资料 / 站点</td><td>共通进度可保留</td><td>凯伊站点仍可能要求相应路线任务</td></tr><tr><td>神赐等级 / 支援 / 成就 / 救世祝福</td><td>共通保留</td><td>跨路线开局即可受益的项目</td></tr><tr><td>共通支线任务</td><td>已完成可自动处理并给奖励</td><td>路线限定任务不直接等同</td></tr><tr><td>声望 / 金钱 / 普通背包 / 角色等级</td><td>不直接复制到另一线开局</td><td>与第三部角色融合、圣柜系统是不同机制</td></tr><tr><td>物品 / 材料 / 军团 / 动物</td><td>首次完成路线后带入第三部；重玩所得通过圣柜生成</td><td>先区分首次结算与额外周目；动物友好可保留，角色融合不复制装备</td></tr></tbody></table></div>${note('圣柜资料记载同一主角再次完成第二部可开放额外周目物品生成；不必为了各路线首次所得专门重打两遍。技能经验资料仍有分歧，暂不按累加安排刷经验。')}<p>${link('https://www.ndw.jp/few-guide-260921-2/','任天堂梦想杂志共通继承说明')} · ${link('https://gamewith.jp/fefw/578172','共通继承')} · ${link('https://appmedia.jp/fe_banshisenkou/80431381','经验另一记载')} · ${link('https://gamewith.jp/fefw/579564','圣柜系统')}</p><div class="section-head"><h2>值得重玩的情况</h2></div><div class="grid-two"><article class="feature"><h3>想兼顾物理与魔法</h3><p>第一轮物理成长、第二轮魔法成长，再融合各项高值和技能。雷电剑、混合职业因此更容易成立，但要计入重玩成本。</p></article><article class="feature"><h3>想补另一套熟练技能</h3><p>保持一轮通关主线清晰，第二轮专门拿缺少的职业熟练。已有高属性项不必重复堆；不同周目仍只有同一名最终角色。</p></article></div>`}
function openPin(id){activeCharacter=null;const p=PINS.find(x=>x.id===id);if(!p)return;const nearby=EQUIPMENT.flatMap(e=>e.sourcesList.filter(s=>s.place&&(s.place===p.name||p.name.includes(s.place))).map(s=>({e,s})));$('#detailContent').innerHTML=`<h1>${esc(p.name)}</h1><p class="heading-meta">${routes[p.area]||p.area} · ${esc(p.type)}</p><p>${esc(p.info)}</p>${nearby.length?'<h2>本站已核实武器来源</h2>'+nearby.map(({e,s})=>`<p><button class="text-button" data-gear="${e.id}">${e.name}</button>：${esc(s.text)}</p>`).join(''):'<p class="muted">此点位的武器清单尚未逐店补全；地图探索材料信息已列出。可在装备页查询已核实购买与兑换来源。</p>'}${link('https://fire-emblem-fw.site/','地图点位出处')}`;$('#detailContent').innerHTML=zhHTML($('#detailContent').innerHTML);openGuideDialog()}
document.addEventListener('click',e=>{if(v9Click(e))return;const ap=e.target.closest('[data-apply-class]');if(ap){selectedClasses[activeCharacter]=ap.dataset.applyClass;openCharacter(activeCharacter,true);return}const sc=e.target.closest('[data-scroll]');if(sc){document.getElementById(sc.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}const fav=e.target.closest('[data-pref]');if(fav){const id=fav.dataset.pref;togglePreference(id);if($('#detail').open&&$('#detailContent').querySelector('[data-pref]'))openCharacter(id,true);return}const action=e.target.closest('[data-pref-action]');if(action){if(action.dataset.prefAction==='undo'){preferences=new Set(preferenceUndo||[]);preferenceUndo=null}else{preferenceUndo=[...preferences];preferences=new Set(action.dataset.prefAction==='restore'?DEFAULT_PREFERENCES:[])}savePreferences();render();return}const rating=e.target.closest('[data-ratings]');if(rating){showRatingGuide();return}const grade=e.target.closest('[data-tier]');if(grade){tier=grade.dataset.tier;render();return}if(e.target.closest('.dialog-nav'))$('#detail').close();if(e.target.closest('a[href^="#"]'))query='';let b=e.target.closest('[data-route],[data-char],[data-family],[data-map],[data-pin],[data-maptype],[data-zoom],[data-class],[data-gear],.close,#themeBtn');if(!b)return;if(b.dataset.route){route=b.dataset.route;query='';family='all';mapType='all';persist();render()}if(b.dataset.char && !window.getSelection?.().toString())openCharacter(b.dataset.char,false,guidePage()==='overview'?route:undefined);if(b.dataset.family){family=b.dataset.family;render()}if(b.dataset.map!==undefined)goMap(b.dataset.map);if(b.dataset.pin&&performance.now()>mapDragUntil){if(activeCharacter&&$('#detail').open)showCharacterPin(b.dataset.pin);else openPin(b.dataset.pin);}if(b.dataset.maptype){mapType=b.dataset.maptype;render()}if(b.dataset.zoom){if(b.dataset.zoom==='0')resetMap();else zoomMap(Number(b.dataset.zoom)>0?1.35:1/1.35);}if(b.dataset.class){$('#detail').close();query=className(b.dataset.class);location.hash='classes';render()}if(b.dataset.gear){$('#detail').close();query='';location.hash='equipment';render();setTimeout(()=>$('#gear-'+b.dataset.gear)?.scrollIntoView({behavior:'smooth',block:'start'}),0)}if(b.matches('.close'))$('#detail').close();if(b.id==='themeBtn'){document.body.classList.toggle('dark');persist()}});
document.addEventListener('change',e=>{v9Change(e)});
const composingSearch=new WeakSet();
function commitSearch(input){const isMain=input.id==='search',isMap=input.matches?.('[data-route-map-search]');if(!isMain&&!isMap)return;const value=input.value,pos=input.selectionStart??value.length,mapRoute=route;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(composingSearch.has(input))return;if(isMain)query=value;else {if(route!==mapRoute)return;routeMapQueries[mapRoute]=value;}render();const next=$(isMain?'#search':'[data-route-map-search]');next?.focus();next?.setSelectionRange(pos,pos)},isMain?120:220)}
document.addEventListener('compositionstart',e=>{if(e.target.id==='search'||e.target.matches?.('[data-route-map-search]')){composingSearch.add(e.target);clearTimeout(searchTimer)}});
document.addEventListener('compositionend',e=>{if(composingSearch.has(e.target)){composingSearch.delete(e.target);commitSearch(e.target)}});
document.addEventListener('input',e=>{if(!e.isComposing&&!composingSearch.has(e.target))commitSearch(e.target)});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
const DEFAULT_PREFERENCES=['c14','c52','c55','c47','c33','c32','c11','c8','c6','c29'];
let preferences=new Set(DEFAULT_PREFERENCES),tier='all',preferenceUndo=null;
try{const saved=localStorage.getItem('guide-preferences-v1');if(saved!==null){const ids=JSON.parse(saved);if(Array.isArray(ids))preferences=new Set(ids.filter(x=>typeof x==='string'&&/^c\d+$/.test(x)))}}catch{}
const isPreferred=c=>preferences.has(c.id);
function savePreferences(){localStorage.setItem('guide-preferences-v1',JSON.stringify([...preferences]))}
function togglePreference(id){if(!DB.characters.some(c=>c.id===id))return;preferences.has(id)?preferences.delete(id):preferences.add(id);savePreferences();render()}
// Lucide star, ISC license: assets/icons/LICENSE-lucide.txt.
function preferenceStar(){return '<svg class="preference-star" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z"/></svg>'}
function preferenceButton(c,compact=false){return `<button class="favorite ${isPreferred(c)?'selected':''} ${compact?'compact':''}" data-pref="${c.id}" aria-pressed="${isPreferred(c)}" aria-label="${isPreferred(c)?'取消':'添加'}偏好：${esc(c.cn)}" title="${isPreferred(c)?'取消偏好':'加入偏好'}">${preferenceStar()}${compact?'':`<span>${isPreferred(c)?'已关注':'关注角色'}</span>`}</button>`}
function firstPartHere(c,r){return c.firstPart&&(c.joinDetails.some(j=>j.route===r+'編'&&j.method!=='対象外'&&j.part==='第一部')||!!c.routes[r])}
function assignmentPurpose(c,r){const special={c14:'固有天马；飞骑主力',c52:'第三部重装治疗；禁止骑飞',c55:'第三部高速法术；直接补入',c47:'弓骑机动＋范围道具袋',c33:'白魔主线；按缺口补黑魔',c32:'拳系物理核心；补力量与精通',c11:'治疗骑兵或枪骑，择一主养',c8:'凯伊补飞行；蕾达可补力量',c6:'剧情治疗位；早期入队，培养窗口更长',c29:'拉近后施法；机动辅助'};return special[c.id]||`${c.role}；${buildPlan(c).end}终点`}
function preferenceEditor(){const list=DB.characters.filter(c=>searchText(c).includes(query.toLowerCase()));return title('偏好与规划','我的角色偏好','关注角色会调整培养总览与跨线分工。偏好自动保存，刷新后保留；各路线推荐和全局装备规划随偏好更新。')+`<div class="preference-summary"><div><strong>${preferences.size}</strong><span>名关注角色</span></div><div><button data-pref-action="clear">清空偏好</button><button data-pref-action="restore">恢复最初偏好</button>${preferenceUndo?'<button data-pref-action="undo">撤销上次重置</button>':''}<a class="button-link" href="#overview">查看调整后的总览 ↗</a></div></div>`+toolbar('搜索63名角色，包括别名…')+`<div class="preference-grid">${list.map(c=>`<article class="preference-item ${isPreferred(c)?'chosen':''}"><button class="preference-person" data-char="${c.id}">${portrait(c)}<span><b>${esc(c.cn)}</b><small data-skill-images="off">${c.rating} · ${esc(c.role)}</small></span></button>${preferenceButton(c,true)}</article>`).join('')}</div>`}
function ratingGuide(){const definitions=[['S','队伍核心','独特行动 / 终局功能难替代，或培养回报显著突出。'],['S-','顶尖主力','主职责或独特功能很强，但晚加入、成长短板或适用条件限制全流程贡献。'],['A+','优先主力','成长、输出或辅助有鲜明优势，定好职业后通常值得优先投入。'],['A','稳定主力','可以长期承担明确职责，但综合优势或独特性比上一档少。'],['A-','条件主力','主职责成立，需补力量、速度、机动，或更依赖特定职业 / 场景。'],['B','实用备选','能补位通关，短板较明显或同职责竞争者更优秀。'],['C','偏好培养','通用竞争力较弱，需要更针对性的资源与装备。']];return `<h1>七档评级怎样看？</h1><p class="heading-meta">编辑评级 · 非官方榜单</p><p>基准是常规通关投入与全流程贡献。考虑最佳可行路线的实际入队窗口、独特能力、成长收益和终局职责；不预设反复刷满。声望影响入队时间，招募花费本身不扣分。晚入队即战力仍有价值，但不能等同于长期贡献。治疗按恢复量、射程与安全评价，重装按承伤与反击评价，不统一拿速度或成长总和打分。</p><div class="rating-criteria">${CATALOG.ratingAudit.criteria.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="rating-distribution">${definitions.map(([t])=>`<div>${ratingBadge(t,false,true)}<b>${DB.characters.filter(c=>c.rating===t).length}人</b></div>`).join('')}</div><div class="table-wrap"><table class="rating-guide-table"><thead><tr><th>档次</th><th>定位</th><th>判断依据</th></tr></thead><tbody>${definitions.map(([t,n,d])=>`<tr><td>${ratingBadge(t,false,true)}</td><td>${n}</td><td>${d}</td></tr>`).join('')}</tbody></table></div><h2>相邻档次的差别</h2><div class="rating-examples">${['c58','c52','c11','c30','c22','c9','c42'].map(id=>DB.characters.find(c=>c.id===id)).map(c=>`<button data-char="${c.id}"><b>${c.rating} · ${c.cn}</b><small>${esc(c.ratingReason)}</small></button>`).join('')}</div><p class="muted">综合评级没有固定名额，也不是成长率总和排名。具体路线推荐还会考虑当时缺什么职责；较低档的开局角色，仍可能比晚来的高档角色更适合当时的缺口；评级不会强行替换已成型主力。</p>`}
function showRatingGuide(){activeCharacter=null;$('#detailContent').innerHTML=ratingGuide();$('#detail').scrollTop=0;if(!$('#detail').open)openGuideDialog()}
