const masteryNotes=CATALOG.masteryNotes;
function multiClassTable(){const list=DB.characters.filter(c=>available(c)&&(family!=='preferred'||isPreferred(c))&&searchText(c).includes(query.toLowerCase()));return `<div class="section-head"><h2>中级 / 上级多职业速查</h2></div><p class="muted">同阶段可换职：先拿资格，再按“补成长 / 拿熟练 / 换职责”选支线。表内副职均为可选，晚加入角色优先使用已有技能。</p><div class="table-wrap"><table><thead><tr><th>角色</th><th>中级 · 20级</th><th>上级 · 35级</th><th>终局与投入</th></tr></thead><tbody>${list.map(c=>{const b=buildPlan(c);return `<tr><td>${tableCharacter(c,{showRating:false,subtitle:arenaRecommendedSubtitle(c)})}</td><td><b>${b.mid[0]}</b>${b.mid[1]?`<small>可选：${esc(b.mid.slice(1).join(' / '))}</small>`:''}</td><td><b>${b.upper[0]}</b>${b.upper[1]?`<small>可选：${esc(b.upper.slice(1).join(' / '))}</small>`:''}</td><td>${b.end}<small>${b.focus}</small></td></tr>`}).join('')}</tbody></table></div><p>${link('https://gamewith.jp/fefw/575722','职业培养依据')} · ${link('https://gamewith.jp/fefw/577435','熟练效果资料')}</p>`}


let searchTimer,mapX=0,mapY=0,mapBase=1,mapFrame=0,mapDragUntil=0;
function zoomAt(scale,x,y,old,px,py){const ratio=scale/old;return [x-(x-px)*ratio,y-(y-py)*ratio]}
function scheduleMap(){if(mapFrame)return;mapFrame=requestAnimationFrame(()=>{mapFrame=0;const c=mapDOM('.map-canvas');if(!c)return;c.style.transform=`translate(${mapX}px,${mapY}px) scale(${mapBase*mapScale})`;c.style.setProperty('--pin-scale',mapBase*mapScale);loadVisibleTiles();mapDOM('.map-viewport')?.classList.toggle('map-detail-zoom',mapScale>=1.8)})}
function clampMap(){const v=mapDOM('.map-viewport');if(!v)return;const b=CATALOG.presentation.mapBounds,scale=mapBase*mapScale;mapX=Math.min(-b.x*scale,Math.max(v.clientWidth-(b.x+b.width)*scale,mapX));mapY=Math.min(-b.y*scale,Math.max(v.clientHeight-(b.y+b.height)*scale,mapY))}
function resetMap(){const v=mapDOM('.map-viewport');if(!v)return;const b=CATALOG.presentation.mapBounds;mapBase=Math.max(v.clientWidth/b.width,v.clientHeight/b.height);mapScale=v.clientWidth<=600?2:1;const scale=mapBase*mapScale;mapX=v.clientWidth/2-(b.x+b.width/2)*scale;mapY=v.clientHeight/2-(b.y+b.height/2)*scale;clampMap();scheduleMap()}
function zoomMap(factor,x,y){const v=mapDOM('.map-viewport');if(!v)return;x??=v.clientWidth/2;y??=v.clientHeight/2;const old=mapScale,next=Math.max(1,Math.min(8,old*factor));[mapX,mapY]=zoomAt(next,x,y,old,mapX,mapY);mapScale=next;clampMap();scheduleMap()}
function loadVisibleTiles(){const v=mapDOM('.map-viewport'),layer=mapDOM('.map-tiles');if(!v||!layer)return;const scale=mapBase*mapScale;if(scale<=0.65){layer.replaceChildren();return}const level=scale>0.65?4:3,size=level===4?128:256,cols=Math.ceil(3328/size),rows=Math.ceil(2560/size);const minX=Math.max(0,Math.floor(-mapX/scale/size)-1),maxX=Math.min(cols-1,Math.floor((v.clientWidth-mapX)/scale/size)+1),minY=Math.max(0,Math.floor(-mapY/scale/size)-1),maxY=Math.min(rows-1,Math.floor((v.clientHeight-mapY)/scale/size)+1);let seen=new Set();for(let x=minX;x<=maxX;x++)for(let y=minY;y<=maxY;y++){const id=`tile-${level}-${x}-${y}`;seen.add(id);if(layer.querySelector('#'+id))continue;const img=document.createElement('img');img.id=id;img.src=`map-tiles/${level}/${x}_${y}.webp`;img.alt='';img.draggable=false;img.decoding='async';img.style.cssText=`position:absolute;left:${x*size}px;top:${y*size}px;width:${size}px;height:${size}px`;layer.appendChild(img)}for(const img of [...layer.children])if(!seen.has(img.id))img.remove()}
function bindMap(){
 const v=mapDOM('.map-viewport');if(!v)return;resetMap();
 v.addEventListener('wheel',e=>{e.preventDefault();const r=v.getBoundingClientRect();zoomMap(Math.exp(-Math.max(-100,Math.min(100,e.deltaY))*.003),e.clientX-r.left,e.clientY-r.top)},{passive:false});
 const pointers=new Map();let gesture=null;
 const sample=()=>{const ps=[...pointers.values()],r=v.getBoundingClientRect();if(ps.length>1)return {x:(ps[0].x+ps[1].x)/2-r.left,y:(ps[0].y+ps[1].y)/2-r.top,d:Math.max(1,Math.hypot(ps[1].x-ps[0].x,ps[1].y-ps[0].y))};return ps.length?{x:ps[0].x-r.left,y:ps[0].y-r.top,d:0}:null};
 const begin=()=>{const s=sample();gesture=s?{...s,scale:mapScale,px:mapX,py:mapY,moved:false}:null};
 v.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});begin();if(pointers.size>1){for(const id of pointers.keys())if(!v.hasPointerCapture(id))v.setPointerCapture(id);mapDragUntil=performance.now()+350;}});
 v.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const s=sample(),dx=s.x-gesture.x,dy=s.y-gesture.y;
 if(s.d||Math.hypot(dx,dy)>5)gesture.moved=true;if(!gesture.moved)return;
 e.preventDefault();mapDragUntil=performance.now()+350;
 if(!v.hasPointerCapture(e.pointerId))v.setPointerCapture(e.pointerId);
 const next=s.d&&gesture.d?Math.max(1,Math.min(8,gesture.scale*s.d/gesture.d)):gesture.scale,ratio=next/gesture.scale;
 mapX=s.x-(gesture.x-gesture.px)*ratio;mapY=s.y-(gesture.y-gesture.py)*ratio;mapScale=next;clampMap();v.classList.add('dragging');scheduleMap();
 });
 const end=e=>{if(!pointers.has(e.pointerId))return;if(gesture?.moved||pointers.size>1)mapDragUntil=performance.now()+350;pointers.delete(e.pointerId);if(v.hasPointerCapture(e.pointerId))v.releasePointerCapture(e.pointerId);v.classList.remove('dragging');begin()};
 v.addEventListener('pointerup',end);v.addEventListener('pointercancel',end);v.addEventListener('lostpointercapture',e=>{if(e.target===v)end(e)});
 v.addEventListener('keydown',e=>{if(['+','=','-','0'].includes(e.key)){e.preventDefault();e.key==='0'?resetMap():zoomMap(e.key==='-'?1/1.35:1.35)}});
}
function outsideDialog(e,d){const r=d.getBoundingClientRect();return e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)}
let backdropDown=false;$('#detail').addEventListener('pointerdown',e=>{backdropDown=outsideDialog(e,$('#detail'))});$('#detail').addEventListener('click',e=>{if(backdropDown&&outsideDialog(e,$('#detail')))$('#detail').close();backdropDown=false});
// Route timing, inline references and complete growth views.
let selectedClasses={},activeCharacter=null,LEARNING=null,learningLoading=false;
function timing(c,r=route){const j=c.joinDetails.find(j=>j.route===r+'編'&&j.part==='第一部'&&j.method!=='対象外'),v=c.routes[r]||{};const renown=Number(j?.renown||v.renown||0),story=j?.method==='ストーリー',chap=Number(String(j?.chapter||'').match(/\d+/)?.[0]||0);const quest=ROUTE_EVENTS.filter(e=>e.route===r&&e.related.includes(c.id));const late=!firstPartHere(c,r)||renown>=8||chap>=9||quest.length;return {j,renown,chap,story,quest,priority:!firstPartHere(c,r)?3:late?2:1,reason:!firstPartHere(c,r)?'后期补入，按即战力补缺':quest.length?'外传完成后才能加入，培养窗口较短':late?'较晚达标，前期用剧情角色过渡':''}}
function routeCost(c,r){const t=timing(c,r);return (t.priority-1)*10+t.renown+t.chap*.3}
function preferenceAssignments(){const rs=Object.keys(routes).filter(r=>r!=='救世篇');return DB.characters.filter(isPreferred).map(c=>{const possible=rs.filter(r=>firstPartHere(c,r));const ranked=[...possible].sort((a,b)=>routeCost(c,a)-routeCost(c,b));return {c,possible,assigned:ranked[0]||'后期'}})}
function routeCandidates(){const base=heroIds().map(n=>DB.characters.find(c=>c.name===n)).filter(Boolean),eligible=c=>route==='救世篇'||firstPartHere(c,route),cap=route==='救世篇'?25:8;const favored=DB.characters.filter(c=>isPreferred(c)&&eligible(c)).sort((a,b)=>routeCost(a,route)-routeCost(b,route));const pool=[...base.filter(eligible),...DB.characters.filter(eligible).sort((a,b)=>timing(a).priority-timing(b).priority||RATING_TIERS.indexOf(a.rating)-RATING_TIERS.indexOf(b.rating))];const out=[],seen=new Set();const add=c=>{if(c&&!seen.has(c.id)&&out.length<cap){seen.add(c.id);out.push(c)}};add(route==='救世篇'?DB.characters.find(c=>c.id==='c58'):base[0]);favored.slice(0,route==='救世篇'?25:5).forEach(add);const heals=['c4','c6','c11','c16','c29','c31','c33','c49','c52'];for(const test of [c=>heals.includes(c.id),c=>c.family==='bow',c=>c.family==='magic'])if(!out.some(test))add(pool.find(c=>test(c)&&!seen.has(c.id)));pool.forEach(add);return out}
function signedGrowth(cl){const max=Math.max(1,...DB.classes.flatMap(c=>Object.values(c.growth||{}).map(v=>Math.abs(Number(v)||0))));return `<div class="modifier-grid">${Object.entries(statNames).map(([k,n])=>{const v=Number(cl.growth?.[k]||0);return `<span class="mod ${v>0?'positive':v<0?'negative':'neutral'}" style="--growth-color:${v===0?'#f8f5ee':growthColor(v,[-max,max])}" title="${n}职业成长修正：${v>0?'+':''}${v}个百分点"><small>${n}</small><b>${v>0?'+':''}${v}</b></span>`}).join('')}</div>`}
function miniGrowth(c){return heat(c.growth)}
function classReason(cl,c){const g=cl.growth||{},b=buildPlan(c);if(cl.col_1==='初级职业')return initialPlan(c,b).name===cl.cn?initialPlan(c,b).reason:'初级职业只作主技能D→C的过渡，不额外练无关技能。';if(/重甲|重装|要塞/.test(cl.cn))return '防御成长'+(g.def>0?'＋':'')+g.def+(b.focus.includes('防御')?'；本线主坦用于守线与承担物理伤害，速度让输出位补足，遇魔法仍需检查魔防。':'；可在备用路线实际升级补防御，融合保留主线速度。');if(cl.cn==='勇士'&&/魔法|治疗/.test(c.role))return '仅有负重缺口才补：力量成长＋20，实际升级累积永久力量；每5力量约增1体格。达到当前装备需求后回法职，战技命中熟练不等于法术命中。';if(cl.cn==='勇士')return '力量成长＋'+g.str+'，服务物理输出；补成长需在此职业升级，熟练可改善战技命中。';if(/剑客|侍道/.test(cl.cn)&&/魔法|治疗/.test(c.role))return '仅在法术主养已完成且缺速度 / 减重能力时使用；剑客速度成长＋15，转勇士需要剑B。纯治疗无缺口时不投入这条支线。';if(/剑客|侍道/.test(cl.cn))return '速度修正'+(g.spd>0?'＋':'')+g.spd+'；兼顾剑系作战与必杀相关熟练，力量不足时另补勇士。';if(/天翼/.test(cl.cn))return '飞行机动服务突击与地形跨越；'+(c.id==='c14'?'自带天马。':'凯伊线可配合骑宠培养。')+'注意飞行技能与骑宠条件。';if(/牧师|主教|贤士|瓦尔基里|游唱/.test(cl.cn))return '以恢复和辅助为主，契合'+b.focus+'；骑乘分支还需对应技能与解锁。';if(/萨满|先知|德鲁伊|魔/.test(cl.cn))return '魔力修正'+(g.mag>0?'＋':'')+g.mag+'，用于法术输出；雷电剑分支需另补剑术，不靠力量替代魔力。';return '服务'+b.focus+'；'+(g.str>=g.mag?'力量':'魔力')+'成长修正'+(Math.max(g.str||0,g.mag||0)>0?'＋':'')+Math.max(g.str||0,g.mag||0)+'。副职仅在需要其成长、熟练或战术时投入。'}
function careerDiagram(c){const b=buildPlan(c),early=initialPlan(c,b),stages=[{names:[early.name],title:early.skip?'初级 · 无需回练':'初级 · 5级起',goal:early.skip?'按入队职业接续':'主技能D → C'}, {names:[...new Set(b.mid)],title:'中级 · 20级',goal:b.goals[0]}, {names:[...new Set(b.upper)],title:'上级 · 35级',goal:b.goals[1]}, {names:[...new Set(b.end.split(' / '))],title:'终局 · 45级起',goal:'主职责终点'}],active=careerStages[c.id]??1;return `<div class="career-view view-switcher" data-view-group="${c.id}" data-view-kind="career"><div class="career-stepper" role="tablist" aria-label="职业培养阶段">${stages.map((stage,i)=>`<button role="tab" id="career-${c.id}-tab-${i}" data-view-tab="${i}" aria-selected="${active===i}" aria-controls="career-${c.id}-panel-${i}" tabindex="${active===i?0:-1}" class="${active===i?'active':''}"><span class="step-number">${String(i+1).padStart(2,'0')}</span><span><b>${stage.title}</b><small>${i===0&&early.skip?esc(c.startClass||'入队职业'):esc(stage.names[0])}</small></span></button>`).join('')}</div>${stages.map((stage,i)=>`<section class="career-panel" role="tabpanel" id="career-${c.id}-panel-${i}" data-view-panel="${i}" aria-labelledby="career-${c.id}-tab-${i}" ${active===i?'':'hidden'}><div class="career-panel-head"><b>${stage.title}</b><small>${esc(stage.goal)}</small></div>${i===0&&early.skip?`<p class="choice-reason">${esc(early.reason)}</p>`:`<div class="career-options">${stage.names.map((n,j)=>stageClass(n,j?'可选副职':'主选',c,{stage:i,mainName:stage.names[0]})).join('')}</div>`}</section>`).join('')}</div><div class="switch-rule"><b>训练顺序</b><span>${emphasis(b.priority)}</span></div>`}
function classIcon(cl,size=40){const id=cl?.id||'',has=CLASS_ICON_IDS.has(id);return `<span class="class-icon${has?'':' class-icon-empty'}" style="--class-icon-size:${size}px" aria-hidden="true">${has?`<img src="assets/classes/${id}.webp" width="${size}" height="${size}" alt="" loading="lazy" decoding="async">`:`<b>${esc((cl?.cn||'?').slice(0,1))}</b>`}</span>`}
