function classCatalogCard(c){const skill=masteryEffect(c);return `<article class="feature class-reference" data-class-row="${c.id}">
 <div class="class-row-name">${classIcon(c,44)}<div><h3><button class="text-button class-name-button" data-reference-type="class" data-reference-id="${c.id}">${esc(c.cn)}</button></h3><small><span class="class-movement">移动 <b>${esc(c.col_34||'—')}</b></span>${c.col_41?`<span>${esc(c.col_41)}</span>`:''}</small></div></div>
 <div class="class-row-requirement"><span class="class-row-label">转职资格</span><p class="class-requirement">${esc(requirement(c))}</p>${c.unlock?`<p class="class-unlock">解锁：${esc(c.unlock)}</p>`:''}</div>
 <div class="class-row-growth"><span class="class-row-label">成长率修正</span>${classGrowthStrip(c)}</div>
 <div class="class-row-mastery"><span class="class-row-label">熟练奖励</span><p><b>${esc(c.col_37||'未记录')}</b>${skill?`<span class="mastery-kind">${esc(skill.type)}</span>`:''}</p><span class="mastery-effect" data-skill-images="off">${esc(skill?.description||'效果尚未核实')}</span></div>
 <div class="class-row-skills"><span class="class-row-label">可用技能</span><div class="class-skill-list">${(c.allowedSkills||[]).map(n=>tag(n)).join('')||'<span class="muted">未记录</span>'}</div></div>
 </article>`}
function classTierRequirements(list,hint){const levels=[...new Set(list.map(c=>c.col_31).filter(Boolean))],renown=[...new Set(list.map(c=>c.col_32).filter(Boolean))];return `<div class="class-tier-requirements">${levels.length?tag('转职等级 '+levels.join(' / ')):tag(hint)}${renown.length?tag('职业声望 '+renown.join(' / ')):''}</div>`}
function classes(){const groups=[['基础职业','基础','入队起点'],['初级职业','初级','5级起'],['中级职业','中级','20级起'],['上级职业','上级','35级起'],['最上级职业','最上级','45级起'],['神将職','神将','后期特殊解锁']],q=query.toLowerCase(),order=list=>classSort?[...list].sort((a,b)=>Number(b.growth?.[classSort]||0)-Number(a.growth?.[classSort]||0)):list,head=`<div class="class-ledger-head" aria-hidden="true"><span>职业</span><span>转职资格</span><span>成长率修正（百分点）</span><span>熟练奖励</span><span>可用技能</span></div>`;return title('职业资料库','职业资格与成长','按职业阶级浏览。修正为成长率的百分点，正负以数值为准；资格和解锁以各职业记录为准。')+toolbar('搜索职业、技能、熟练奖励…')+`<div class="class-ledger-tools"><div class="class-group-nav">${groups.map(([key,label],i)=>`<button data-scroll="class-group-${i}">${label} <small>${DB.classes.filter(c=>c.col_1===key).length}</small></button>`).join('')}</div><label class="class-sort">按修正排序<select data-class-sort aria-label="按成长修正排序"><option value="">默认顺序</option>${CLASS_GROWTH_ORDER.map(k=>`<option value="${k}" ${classSort===k?'selected':''}>${statNames[k]}从高到低</option>`).join('')}</select></label></div>`+(!DB.classes.some(c=>searchText(c).includes(q))?'<p class="empty-state">没有匹配职业，请修改关键词或清空搜索。</p>':'')+groups.map(([key,label,hint],i)=>{const list=order(DB.classes.filter(c=>c.col_1===key&&searchText(c).includes(q)));return list.length?`<section class="class-tier-group" id="class-group-${i}"><div class="class-tier-heading"><h2>${label}职业 ${tag(list.length+'种')}</h2>${classTierRequirements(DB.classes.filter(c=>c.col_1===key),hint)}</div><div class="class-catalog class-ledger">${head}${list.map(classCatalogCard).join('')}</div></section>`:''}).join('')}
document.addEventListener('change',e=>{const t=e.target;if(!t.matches?.('[data-class-sort]'))return;classSort=t.value;render();document.querySelector('[data-class-sort]')?.focus()});
function routeEquipment(candidates){const entries=new Map();for(const c of candidates){let ids={sword:['daminasword','clean'],axe:['daminaaxe'],fist:['daminafist'],bow:['damina_bow','longbow'],magic:['magic_staff','heal'],dancer:['clean','swift'],lance:['aurora_lance']}[c.family]||[];if(c.id==='c7')ids=['clean','carla','swift'];for(const id of ids){const e=EQUIPMENT.find(e=>e.id===id);if(!e)continue;if(!entries.has(id))entries.set(id,{e,users:[]});entries.get(id).users.push(c)}}return [...entries.values()]}
function routeCollection(entries){return entries.map(({e,users})=>{const buy=e.sourcesList.find(s=>s.kind.includes('购买'));const exchange=e.sourcesList.find(s=>s.kind.includes('兑换'));const source=buy||exchange||e.sourcesList[0];const mats=buy?[]:e.materials.filter(m=>source?.text.includes(m[0]));return {e,users,source,mats,buy}})}
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('.char-card[data-char]')){e.preventDefault();openCharacter(e.target.dataset.char)}});
